// n8n Code node, before normalization/reservation. Key is runtime env only.
const reject = () => [{json:{body:{},ingress_verified:false,error_code:'ingress_unverified'}}];
try {
  const crypto = require('crypto');
  const key = $env.DIS_GATEWAY_HMAC_KEY;
  const headers = $json.headers ?? {};
  const timestamp = headers['x-dis-proof-time'];
  const signature = headers['x-dis-proof'];
  const body = $json.body;
  if (typeof key !== 'string' || key.length < 32 || !body || typeof body !== 'object' || Array.isArray(body)) return reject();
  if (typeof timestamp !== 'string' || !/^\d{10}$/.test(timestamp) || typeof signature !== 'string' || !/^[0-9a-f]{64}$/.test(signature)) return reject();
  const age = Math.floor(Date.now()/1000)-Number(timestamp);
  if (age > 300 || age < -30) return reject();
  function canonical(v) {
    if (v === null || typeof v !== 'object') return JSON.stringify(v);
    if (Array.isArray(v)) return '['+v.map(canonical).join(',')+']';
    return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';
  }
  const expected = crypto.createHmac('sha256',key).update(`dis-core-ingress:v1\n${timestamp}\n${canonical(body)}`).digest();
  if (!crypto.timingSafeEqual(Buffer.from(signature,'hex'),expected)) return reject();
  return [{json:{body,ingress_verified:true}}];
} catch { return reject(); }

const body = $json.body ?? $json;
const validObject = body && typeof body === 'object' && !Array.isArray(body);
const p = validObject ? body : {};
const ID = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/;
const EXT = /^[A-Za-z0-9_.:-]{1,160}$/;
const CHANNEL = /^(telegram|api|web|webhook)$/;
// Trusted ingress contract only. Raw Telegram/API bypass is rejected here.
const trusted = $json.ingress_verified === true && p.ingress?.authenticated_source === true;
const channel = typeof p.channel === 'string' ? p.channel : '';
const project_id = typeof p.project_id === 'string' ? p.project_id : '';
const bot_id = typeof p.bot_id === 'string' ? p.bot_id : '';
const source_id = typeof p.source_id === 'string' ? p.source_id : '';
function safeToken(value) {
  if (typeof value === 'number' && !Number.isSafeInteger(value)) return '';
  if (typeof value !== 'number' && typeof value !== 'string') return '';
  const text=String(value);
  if (/^-?\d+$/.test(text)) {
    if (!/^(?:0|-?[1-9]\d{0,19})$/.test(text)) return '';
    try { const id=BigInt(text); if(id < -9223372036854775808n || id > 9223372036854775807n) return ''; } catch { return ''; }
  }
  return text;
}
const dialogue_id = safeToken(p.dialogue_id);
const external_event_id = safeToken(p.external_event_id ?? p.event_id);
const external = p.user_id ?? null;
let user_id = null;
let validUser = false;
if ((typeof external === 'string' || Number.isSafeInteger(external)) && /^-?[1-9]\d{0,18}$|^0$/.test(String(external))) {
  try {
    const value = BigInt(external);
    validUser = value >= -9223372036854775808n && value <= 9223372036854775807n;
    if (validUser) user_id = String(external);
  } catch { validUser = false; }
}
const validScope = trusted && CHANNEL.test(channel) && ID.test(project_id) && ID.test(bot_id)
  && (source_id === '' || ID.test(source_id)) && EXT.test(external_event_id)
  && /^[A-Za-z0-9_.:-]{1,160}$/.test(dialogue_id)
  && !channel.includes('|') && !project_id.includes('|') && !bot_id.includes('|');
const source = channel === 'telegram' ? 'telegram' : (channel === 'api' || channel === 'web' ? channel : 'webhook');
const event_type = p.payload?.callback_data !== undefined || p.event_type === 'callback_query'
  ? 'callback_query'
  : (p.payload?.text !== undefined || p.event_type === 'message' ? 'message' : 'webhook');
const payload = (p.payload && typeof p.payload === 'object' && !Array.isArray(p.payload)) ? p.payload : {};
return [{json:{
  source, channel, project_id, bot_id, source_id, dialogue_id,
  external_event_id, user_id, event_type, payload,
  ingress: {authenticated_source: trusted, end_user_authenticated: false},
  received_at:new Date().toISOString(), execution_id:String($execution.id),
  ...($json.error_code ? {error_code:'ingress_unverified'} : {}),
  valid: Boolean(validObject && trusted && validUser && validScope)
}}];

const crypto = require('crypto');
const j = $json;
const correlation_id = `COR-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${crypto.randomUUID()}`;
// Composite key: channel|project|bot|external. Segments forbid '|', so no collisions.
const event_id = j.valid
  ? `${j.channel}|${j.project_id}|${j.bot_id}|${j.external_event_id}`
  : null;
const execution_id = `${j.execution_id}:${crypto.randomUUID()}`;
return [{json:{...j,event_id,correlation_id,execution_id}}];

const j = $json;
const p = j.payload ?? {};
const text = p.text;
const callback = p.callback_data;
const payload = {};
if (typeof text === 'string') payload.text = text.slice(0,4096);
if (typeof callback === 'string') payload.callback_data = callback.slice(0,512);
return [{json:{...j,payload}}];

const j = $json.result;
if (!j || typeof j !== 'object') throw new Error('Invalid database result');
return [{json:{...j,...(!j.persistence?.recorded ? {error_code:'persistence_conflict'} : {})}}];

let j = $('Sanitize Payload').first().json;
for (const name of ['Call WF-04','Call WF-03','Call WF-02','Call WF-01']) {
  try {
    const value = $(name).first().json;
    if (value.event_id && !value.error) { j = value; break; }
  } catch {}
}
// Never pass raw engine/SQL error text to persistence or the HTTP response.
return [{json:{...j,error_code:'core_processing_error'}}];

const j = $json.result;
if (!j || typeof j !== 'object') throw new Error('Invalid database result');
return [{json:j}];

const j = $json;
const d = j.idempotency ?? {};
let status = 'completed';
let http_status = 200;
let message = 'Событие обработано: определён маршрут; бизнес-действия не выполнялись.';
if (j.error_code === 'ingress_unverified') { status='rejected'; http_status=401; message='Неподтверждённый внутренний запрос.'; }
else if (!j.valid) { status = 'invalid_event'; http_status = 400; message = 'Нужны доверенный вход, стабильный external_event_id и корректный внешний идентификатор.'; }
else if (j.error_code) { status = 'failed'; http_status = 503; message = 'Обработка временно недоступна.'; }
else if (d.rejected) { status = 'invalid_event'; http_status = 400; message = 'Отсутствует область источника.'; }
else if (d.duplicate) { status = 'duplicate'; message = 'Событие уже обработано.'; }
else if (d.busy) { status = 'busy'; http_status = 409; message = 'Событие уже обрабатывается.'; }
else if (d.failed) { status = 'previous_failed'; http_status = 409; message = 'Предыдущая обработка завершилась ошибкой; автоматический повтор отключён.'; }
else if (j.context?.rejected) { status='rejected'; http_status=403; message='Доступ к контексту запрещён.'; }
else if (j.auth?.registration_required) { status = 'registration_required'; message = 'Требуется регистрация.'; }
else if (j.auth && !j.auth.allowed) { status = 'rejected'; http_status = 403; message = 'Доступ ограничен.'; }
else if (j.context?.processing_lock) { status = j.context.stale ? 'context_stale' : 'context_busy'; http_status = 409; message = 'Контекст заблокирован; обработка не продолжена.'; }
else if (j.context && !['active','expired'].includes(j.context.status)) { status = 'context_inactive'; http_status = 409; message = 'Контекст недоступен для обработки.'; }
else if (j.routing?.route === 'unknown') { message = 'Событие принято; маршрут не определён.'; }
const states = new Set(['new','awaiting_input','processing','awaiting_payment','awaiting_approval','completed','expired','failed']);
const body = {event_id:j.event_id,external_event_id:j.external_event_id,correlation_id:j.correlation_id,
  source:j.source,channel:j.channel,project_id:j.project_id,bot_id:j.bot_id,
  user_id:j.user_id,dialogue_id:j.dialogue_id,event_type:j.event_type,received_at:j.received_at,status,
  duplicate:Boolean(d.duplicate),busy:Boolean(d.busy),message};
if (j.auth) body.auth = {found:j.auth.found,registration_required:j.auth.registration_required,allowed:j.auth.allowed};
if (j.context?.rejected) body.context={rejected:true,reason:'user_scope_mismatch'};
else if (j.context) body.context = {exists:j.context.exists,state:states.has(j.context.state)?j.context.state:'new',
  expired:j.context.expired,stale:j.context.stale,processing_lock:j.context.processing_lock};
if (j.routing) body.routing = j.routing;
if (j.error_code) body.error = 'core_processing_error';
return [{json:{http_status,body}}];
